-- 0063_features_1019: the 2026-10-19 feature batch in one migration (admin workload, calendar
-- feed ADR 0051, ticket rating, AI ticket drafts ADR 0053, message search ADR 0057, weekly
-- client summaries ADR 0055, audit log ADR 0054). Generated by drizzle-kit, plus the
-- hand-written audit_log guard function and trigger at the end. messages.search_text uses
-- spolu_fold (created by 0062_night_integration); adding it rewrites messages once.
CREATE TABLE "audit_log" (
	"id" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"actor_kind" text NOT NULL,
	"actor_user_id" text,
	"actor_token_id" text,
	"actor_label" text NOT NULL,
	"actor_detail" text,
	"entity_type" text NOT NULL,
	"entity_id" text NOT NULL,
	"entity_label" text NOT NULL,
	"group_id" text,
	"category" text DEFAULT 'general' NOT NULL,
	"action" text NOT NULL,
	"changes" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"cause_id" text,
	CONSTRAINT "audit_log_actor_kind_check" CHECK ("audit_log"."actor_kind" in ('user', 'mcp', 'egrant', 'system')),
	CONSTRAINT "audit_log_category_check" CHECK ("audit_log"."category" in ('general', 'finance')),
	CONSTRAINT "audit_log_actor_check" CHECK (("audit_log"."actor_kind" in ('user', 'mcp')) = ("audit_log"."actor_user_id" is not null)),
	CONSTRAINT "audit_log_token_check" CHECK (("audit_log"."actor_kind" = 'mcp') = ("audit_log"."actor_token_id" is not null)),
	CONSTRAINT "audit_log_changes_size_check" CHECK (pg_column_size("audit_log"."changes") <= 16384)
);
--> statement-breakpoint
